71	static int _svm_register_for_each_seg(
72	    u32 dst_devid, int (*handle)(void *va_handle, u64 start, struct svm_global_va *src_info, void *priv), void *priv)
73	{
74	    struct list_head *node = NULL, *tmp = NULL;
75	    int ret;
76	
77	    list_for_each_safe(node, tmp, &register_head)
78	    {
79	        struct svm_register_node *register_node = list_entry(node, struct svm_register_node, node);
80	        void *va_handle = register_node->is_non_svm ? NULL : svm_handle_get(register_node->va);
81	        if ((register_node->is_non_svm) ||
82	            (va_handle != NULL)) { /* get va handle to access its priv svmm_inst in node */
83	            ret = svm_svmm_for_each_seg_handle(register_node->svmm_inst[dst_devid], handle, priv);
84	            if (va_handle != NULL) {
85	                svm_handle_put(va_handle);
86	            }
87	            if (ret != 0) {
88	                svm_err("Svm register for each seg failed. (devid=%u)\n", dst_devid);
89	                return ret;
90	            }
91	        }
92	    }
93	    return 0;
94	}
