96	int svm_register_for_each_seg(u32 dst_devid,
97	                              int (*handle)(void *va_handle, u64 start, struct svm_global_va *src_info, void *priv),
98	                              void *priv)
99	{
100	    int ret;
101	
102	    if (dst_devid >= SVM_MAX_DEV_NUM) {
103	        svm_err("Devid is invalid. (devid=%u)\n", dst_devid);
104	        return DRV_ERROR_INVALID_VALUE;
105	    }
106	
107	    (void)pthread_mutex_lock(&register_mutex);
108	    ret = _svm_register_for_each_seg(dst_devid, handle, priv);
109	    (void)pthread_mutex_unlock(&register_mutex);
110	    return ret;
111	}
