113	static int svm_register_to_peer_alloc_va(u32 devid, u64 size, u64 *va)
114	{
115	    u32 normal_flag = SVM_NORMAL_MALLOC_FLAG_VA_ONLY | SVM_NORMAL_MALLOC_FLAG_VA_WITH_MASTER;
116	    u64 npage_size;
117	    u64 tmp_va = 0;
118	    int ret;
119	
120	    ret = svm_dbi_query_npage_size(devid, &npage_size);
121	    if (ret != 0) {
122	        svm_err("Get npage size failed. (devid-%u)\n", devid);
123	        return ret;
124	    }
125	
126	    ret = svm_normal_malloc(SVM_INVALID_DEVID, normal_flag, npage_size, &tmp_va, svm_get_non_dev_align_size(size));
127	    if (ret != 0) {
128	        svm_err("Alloc va failed. (devid=%u; size=%llu)\n", devid, size);
129	        return ret;
130	    }
131	
132	    *va = tmp_va;
133	    return 0;
134	}
