155	static void svm_register_dst_recycle_proc(u32 devid, u32 udevid, void *svmm_inst)
156	{
157	    u32 recyle_num = 0;
158	
159	    /* recycle dst devid match */
160	    while (1) {
161	        struct svm_global_va src_info;
162	        struct svm_dst_va dst_info;
163	        u64 va, svm_flag;
164	        u32 smm_flag = 0;
165	        int ret;
166	
167	        ret = svm_svmm_get_first_seg(svmm_inst, &devid, &va, &svm_flag, &src_info);
168	        if (ret != 0) {
169	            break;
170	        }
171	
172	        register_ops_pre_unmap(&src_info, devid, va);
173	
174	        svm_dst_va_pack(devid, PROCESS_CP1, va, src_info.size, &dst_info);
175	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
176	        if (svm_va_is_in_range(src_info.va, src_info.size) == false) {
177	            svm_register_to_peer_free_va(devid, va, src_info.size);
178	        }
179	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info.size, true);
180	        recyle_num++;
181	    }
182	
183	    if (recyle_num > 0) {
184	        svm_info("Recycle success. (devid=%u; udevid=%u; recyle_num=%u)\n", devid, udevid, recyle_num);
185	    }
186	}
