188	static void svm_register_dst_recycle(u32 devid)
189	{
190	    struct list_head *node = NULL, *tmp = NULL;
191	    u32 udevid;
192	
193	    if (uda_get_udevid_by_devid_ex(devid, &udevid) != 0) {
194	        svm_err("Get udevid failed. (devid=%u)\n", devid);
195	        return;
196	    }
197	
198	    list_for_each_safe(node, tmp, &register_head)
199	    {
200	        struct svm_register_node *register_node = list_entry(node, struct svm_register_node, node);
201	        void *va_handle = register_node->is_non_svm ? NULL : svm_handle_get(register_node->va);
202	        if ((register_node->is_non_svm) ||
203	            (va_handle != NULL)) { /* get va handle to access its priv svmm_inst in node */
204	            svm_register_dst_recycle_proc(devid, udevid, register_node->svmm_inst[devid]);
205	            if (va_handle != NULL) {
206	                svm_handle_put(va_handle);
207	            }
208	        }
209	    }
210	}
