239	static void svm_register_svmm_destroy_insts(struct svm_register_node *register_node)
240	{
241	    u32 devid;
242	
243	    for (devid = 0; devid < SVM_MAX_DEV_NUM; devid++) {
244	        svm_svmm_destroy_inst(register_node->svmm_inst[devid]);
245	    }
246	}
