248	static int svm_register_svmm_create_insts(struct svm_register_node *register_node, u64 start, u64 size, u64 svm_flag)
249	{
250	    void *svmm_inst = NULL;
251	    u32 devid, tmp_devid;
252	
253	    for (devid = 0; devid < SVM_MAX_DEV_NUM; devid++) {
254	        svmm_inst = svm_svmm_create_inst(start, size, SVMM_NON_OVERLAP, svm_flag);
255	        if (svmm_inst == NULL) {
256	            svm_err("Create inst priv failed. (va=0x%llx)\n", start);
257	            goto destroy_insts;
258	        }
259	
260	        register_node->svmm_inst[devid] = svmm_inst;
261	    }
262	
263	    return DRV_ERROR_NONE;
264	destroy_insts:
265	    for (tmp_devid = 0; tmp_devid < devid; tmp_devid++) {
266	        svm_svmm_destroy_inst(register_node->svmm_inst[tmp_devid]);
267	        register_node->svmm_inst[tmp_devid] = NULL;
268	    }
269	    return DRV_ERROR_OUT_OF_MEMORY;
270	}
