286	static int svm_register_svmm_inst_release(void *svmm_inst, u32 devid, bool force)
287	{
288	    u32 recyle_num = 0;
289	
290	    while (1) {
291	        struct svm_global_va src_info;
292	        struct svm_dst_va dst_info;
293	        u64 va, svm_flag;
294	        u32 smm_flag = 0;
295	        u32 tmp_devid;
296	        int ret;
297	
298	        ret = svm_svmm_get_first_seg(svmm_inst, &tmp_devid, &va, &svm_flag, &src_info);
299	        if (ret != 0) {
300	            break;
301	        }
302	
303	        if (force == false) {
304	            return DRV_ERROR_BUSY;
305	        }
306	
307	        register_ops_pre_unmap(&src_info, devid, va);
308	
309	        svm_dst_va_pack(devid, PROCESS_CP1, va, src_info.size, &dst_info);
310	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
311	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info.size, true);
312	        recyle_num++;
313	    }
314	
315	    if (recyle_num > 0) {
316	        u64 svmma_start, svmma_size, svm_flag;
317	        svm_svmm_parse_inst_info(svmm_inst, &svmma_start, &svmma_size, &svm_flag);
318	        svm_info("Release success. (va=0x%llx; size=0x%llx; devid=%u; recyle_num=%u)\n", svmma_start, svmma_size, devid,
319	                 recyle_num);
320	    }
321	
322	    return DRV_ERROR_NONE;
323	}
324	
325	static int svm_register_svmm_release(void *priv, bool force)
326	{
327	    struct svm_register_node *register_node = (struct svm_register_node *)priv;
328	    u32 devid;
329	    int ret;
330	
331	    for (devid = 0; devid < SVM_MAX_DEV_NUM; devid++) {
332	        ret = svm_register_svmm_inst_release(register_node->svmm_inst[devid], devid, force);
333	        if (ret != DRV_ERROR_NONE) {
334	            return ret;
335	        }
336	    }
337	    svm_register_svmm_destroy(register_node);
338	    return 0;
339	}
