364	static struct svm_register_node *svm_register_non_svm_svmm_create(u64 start, u64 size, u64 svm_flag)
365	{
366	    struct svm_register_node *register_node = NULL;
367	    int ret;
368	
369	    register_node = (struct svm_register_node *)svm_ua_calloc(1, sizeof(*register_node));
370	    if (register_node == NULL) {
371	        svm_err("Malloc failed.\n");
372	        return NULL;
