415	static void *svm_register_get_non_svm_svmm_inst(u32 src_devid, u32 dst_devid)
416	{
417	    struct svm_register_node *register_node = NULL;
418	
419	    if ((src_devid >= SVM_MAX_DEV_NUM) || (dst_devid >= SVM_MAX_DEV_NUM)) {
420	        return NULL;
421	    }
422	
423	    (void)pthread_mutex_lock(&register_mutex);
424	    register_node = non_svm_register_node[src_devid];
425	    if (register_node != NULL) {
426	        (void)pthread_mutex_unlock(&register_mutex);
427	        return register_node->svmm_inst[dst_devid];
428	    }
429	
430	    register_node = svm_register_non_svm_svmm_create(0, MAX_VA_SIZE, 0);
431	    if (register_node == NULL) {
432	        (void)pthread_mutex_unlock(&register_mutex);
433	        svm_err("Create failed. (devid=%d)\n", src_devid);
434	        return NULL;
435	    }
436	
437	    non_svm_register_node[src_devid] = register_node;
438	    (void)pthread_mutex_unlock(&register_mutex);
439	    return register_node->svmm_inst[dst_devid];
440	}
