493	static void *svm_normal_create_register_svmm(void *va_handle, u32 devid, u64 start, u64 size, u64 svm_flag)
494	{
495	    void *svmm_inst = NULL;
496	
497	    (void)pthread_mutex_lock(&register_mutex);
498	    svmm_inst = svm_normal_get_register_svmm(va_handle, devid);
499	    if (svmm_inst == NULL) {
500	        struct svm_register_node *register_node = svm_register_svmm_create(start, size, svm_flag);
501	        if (register_node != NULL) {
502	            int ret = svm_set_priv(va_handle, (void *)register_node, &register_priv_ops);
503	            if (ret == 0) {
504	                svmm_inst = register_node->svmm_inst[devid];
505	            } else { /* may be set by prefetch */
506	                svm_err("Set va priv failed. (start=0x%llx)\n", start);
507	                svm_register_svmm_destroy_locked(register_node);
508	            }
509	        }
510	    }
511	    (void)pthread_mutex_unlock(&register_mutex);
512	
513	    return svmm_inst;
514	}
