547	static int svm_register(void *svmm_inst, u64 va, u64 size, u32 devid, struct svm_global_va *src_info)
548	{
549	    struct svm_dst_va dst_info;
550	    u64 svm_flag = 0;
551	    u32 smm_flag = 0;
552	    int ret;
553	
554	    ret = uda_get_udevid_by_devid_ex(src_info->udevid, &src_info->udevid);
555	    if (ret != DRV_ERROR_NONE) {
556	        svm_err("Get udevid failed. (devid=%u; ret=%d)\n", devid, ret);
557	        return ret;
558	    }
559	
560	    ret = svm_svmm_add_seg(svmm_inst, devid, va, svm_flag, src_info);
561	    if (ret != 0) {
562	        svm_err("Add seg failed. (devid=%u; va=0x%llx)\n", devid, va);
563	        return ret;
564	    }
565	
566	    svm_dst_va_pack(devid, PROCESS_CP1, va, size, &dst_info);
567	
568	    ret = svm_smm_client_map(&dst_info, src_info, smm_flag);
569	    if (ret != 0) {
570	        svm_err("Smm map failed. (devid=%u; va=0x%llx)\n", devid, va);
571	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info->size, true);
572	        return ret;
573	    }
574	
575	    ret = register_ops_post_map(src_info, devid, va);
576	    if (ret != 0) {
577	        svm_err("Smm map failed. (devid=%u; va=0x%llx)\n", devid, va);
578	        (void)svm_smm_client_unmap(&dst_info, src_info, smm_flag);
579	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info->size, true);
580	        return ret;
581	    }
582	
583	    return ret;
584	}
585	
586	static int svm_unregister(void *svmm_inst, u64 va, u32 devid)
587	{
588	    struct svm_dst_va dst_info;
589	    struct svm_global_va src_info;
590	    u64 start = va;
591	    u64 svm_flag = 0;
592	    u32 smm_flag = 0;
593	    int ret;
594	
595	    ret = svm_svmm_get_seg_by_va(svmm_inst, &devid, &start, &svm_flag, &src_info);
596	    if (ret != 0) {
597	        svm_err("Addr is not register. (va=0x%llx; devid=%u)\n", start, devid);
598	        return DRV_ERROR_PARA_ERROR;
599	    }
600	    if (va != start) {
601	        svm_err("Should be the registered start va. (va=0x%llx; start=0x%llx)\n", va, start);
602	        return DRV_ERROR_PARA_ERROR;
603	    }
604	
605	    register_ops_pre_unmap(&src_info, devid, start);
606	
607	    svm_dst_va_pack(devid, PROCESS_CP1, start, src_info.size, &dst_info);
608	    ret = svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
609	    if (ret != 0) {
610	        svm_warn("Smm unmap failed. (devid=%u; va=0x%llx)\n", devid, start);
611	    }
612	
613	    (void)svm_svmm_del_seg(svmm_inst, devid, start, src_info.size, true);
614	
615	    return ret;
616	}
