618	static int svm_vmm_register(void *va_handle, u64 va, u64 size, u32 devid)
619	{
620	    void *vmm_svmm_inst = NULL, *register_svmm_inst = NULL;
621	    void *seg_handle = NULL;
622	    u32 seg_devid;
623	    u64 svm_flag, seg_va;
624	    struct svm_global_va src_info;
625	    int ret;
626	
627	    vmm_svmm_inst = vmm_get_svmm(va_handle);
628	    if (vmm_svmm_inst == NULL) {
629	        svm_err("Vmm alloc not finish. (va=0x%llx)\n", va);
630	        return DRV_ERROR_PARA_ERROR;
631	    }
632	
633	    seg_handle = svm_svmm_seg_handle_get(vmm_svmm_inst, va);
634	    if (seg_handle == NULL) { /* maybe va has been unmap after get prop or not map */
635	        svm_err("Get seg handle failed. (va=%llx)\n", va);
636	        return DRV_ERROR_PARA_ERROR;
637	    }
638	
639	    /* seg va may be update to seg start va which is small than register va */
640	    seg_va = va;
641	    ret = svm_svmm_get_seg_by_va(vmm_svmm_inst, &seg_devid, &seg_va, &svm_flag, &src_info);
642	    if (ret != 0) {
643	        svm_svmm_seg_handle_put(seg_handle);
644	        /* should not in, because we has been get seg handle */
645	        svm_err("Get seg info failed. (va=%llx)\n", va);
646	        return ret;
647	    }
648	
649	    vmm_restore_real_src_va(&src_info);
650	
651	    register_svmm_inst = svm_vmm_get_register_svmm(seg_handle, devid);
652	    if (register_svmm_inst == NULL) { /* vmm map addr first register */
653	        register_svmm_inst = svm_vmm_create_register_svmm(seg_handle, devid, seg_va, src_info.size, svm_flag);
654	        if (register_svmm_inst == NULL) {
655	            svm_svmm_seg_handle_put(seg_handle);
656	            return DRV_ERROR_OUT_OF_MEMORY;
657	        }
658	    }
659	
660	    /* update register va real src info */
661	    src_info.va += va - seg_va;
662	    src_info.size = size;
663	    ret = svm_register(register_svmm_inst, va, size, devid, &src_info);
664	    if (ret == 0) {
665	        u64 flag = svm_flag | SVM_FLAG_CAP_LDST;
666	        svm_svmm_mod_seg_svm_flag(seg_handle, flag);
667	    }
668	
669	    svm_svmm_seg_handle_put(seg_handle);
670	
671	    return ret;
672	}
