758	static int svm_register_user_malloc_para_check(u64 va, u64 size, u32 devid)
759	{
760	    u64 npage_size;
761	    int ret;
762	
763	    if (devid >= SVM_MAX_DEV_AGENT_NUM) {
764	        svm_err("Invalid para. (devid=%u)\n", devid);
765	        return DRV_ERROR_INVALID_DEVICE;
766	    }
767	
768	    ret = svm_dbi_query_npage_size(devid, &npage_size);
769	    if (ret != 0) {
770	        svm_err("Get npage size failed. (devid=%u)\n", devid);
771	        return DRV_ERROR_INNER_ERR; /* Same to pcie th scene. */
772	    }
773	
774	    if ((va == 0) || (size == 0)) {
775	        svm_err("Src_va is zero or map_size is zero. (src_va=0x%llx; size=%llu)\n", va, size);
776	        return DRV_ERROR_INVALID_VALUE;
777	    }
778	
779	    if (SVM_IS_ALIGNED(va, npage_size) == false) {
780	        svm_err("Src_va not page alignment. (src_va=0x%llx; page_size=%llu)\n", va, npage_size);
781	        return DRV_ERROR_PARA_ERROR;
782	    }
783	
784	    return 0;
785	}
