787	static int svm_register_user_malloc_to_peer(u64 va, u64 size, u32 devid, u64 *dst_va)
788	{
789	    u64 alloc_va, svm_flag, tmp_va, aligned_size;
790	    u32 host_devid = svm_get_host_devid();
791	    struct svm_global_va src_info;
792	    void *svmm_inst = NULL;
793	    int ret;
794	
795	    ret = svm_register_user_malloc_para_check(va, size, devid);
796	    if (ret != 0) {
797	        return ret;
798	    }
799	
800	    svmm_inst = svm_register_get_non_svm_svmm_inst(host_devid, devid);
801	    if (svmm_inst == NULL) {
802	        svm_err("Init failed.\n");
803	        return DRV_ERROR_INNER_ERR;
804	    }
805	
806	    ret = svm_get_aligned_size(devid, 0ULL, size, &aligned_size);
807	    if (ret != 0) {
808	        svm_err("Get aligned size failed. (devid=%u; size=%llu)\n", devid, size);
809	        return ret;
810	    }
811	
812	    svm_global_va_pack(host_devid, svm_getpid(), va, aligned_size, &src_info);
813	    ret = svm_svmm_get_seg_by_src_udevid_and_va(svmm_inst, &devid, &tmp_va, &svm_flag, &src_info);
814	    if (ret == 0) {
815	        svm_err("Addr is already register to device. (va=0x%llx; devid=%u)\n", va, devid);
816	        return DRV_ERROR_REPEATED_USERD;
817	    }
818	
819	    ret = svm_register_to_peer_alloc_va(devid, aligned_size, &alloc_va);
820	    if (ret != 0) {
821	        return ret;
822	    }
823	
824	    ret = svm_register(svmm_inst, alloc_va, aligned_size, devid, &src_info);
825	    if (ret != 0) {
826	        svm_register_to_peer_free_va(devid, alloc_va, aligned_size);
827	        svm_err("Svm register failed. (va=0x%llx; size=%llu; devid=%u)\n", va, size, devid);
828	        return ret;
829	    }
830	
831	    *dst_va = alloc_va;
832	    return 0;
833	}
