835	static int svm_unregister_user_malloc_to_peer(u64 va, u32 devid)
836	{
837	    u32 host_devid = svm_get_host_devid();
838	    struct svm_global_va src_info;
839	    void *svmm_inst = NULL;
840	    u64 dst_va, svm_flag;
841	    int ret;
842	
843	    if (devid >= SVM_MAX_DEV_AGENT_NUM) {
844	        svm_err("Invalid para. (devid=%u)\n", devid);
845	        return DRV_ERROR_INVALID_DEVICE;
846	    }
847	
848	    svmm_inst = svm_register_get_non_svm_svmm_inst(host_devid, devid);
849	    if (svmm_inst == NULL) {
850	        svm_err("Init failed.\n");
851	        return DRV_ERROR_INNER_ERR;
852	    }
853	
854	    svm_global_va_pack(host_devid, svm_getpid(), va, 0, &src_info);
855	    ret = svm_svmm_get_seg_by_src_udevid_and_va(svmm_inst, &devid, &dst_va, &svm_flag, &src_info);
856	    if (ret != 0) {
857	        svm_err("Hasn't register. (va=0x%llx; devid=%u)\n", va, devid);
858	        return ret;
859	    }
860	
861	    ret = svm_unregister(svmm_inst, dst_va, devid);
862	    if (ret != 0) {
863	        svm_err("Svm unregister failed. (va=0x%llx; devid=%u)\n", va, devid);
864	        return ret;
865	    }
866	
867	    svm_register_to_peer_free_va(devid, dst_va, src_info.size);
868	    return 0;
869	}
