871	static int svm_register_svm_to_peer_para_check(u64 va, u64 size, u32 devid)
872	{
873	    u32 host_devid = svm_get_host_devid();
874	    struct svm_prop prop;
875	    int ret;
876	
877	    if (devid >= SVM_MAX_DEV_NUM) {
878	        svm_err("Invalid para. (devid=%u)\n", devid);
879	        return DRV_ERROR_INVALID_DEVICE;
880	    }
881	
882	    ret = svm_get_prop(va, &prop);
883	    if (ret != 0) {
884	        svm_err("Get prop failed. (va=0x%llx)\n", va);
885	        return DRV_ERROR_PARA_ERROR;
886	    }
887	
888	    if (!svm_flag_cap_is_support_register(prop.flag)) {
889	        svm_err("Addr cap is not support register. (va=0x%llx)\n", va);
890	        return DRV_ERROR_PARA_ERROR;
891	    }
892	
893	    if (!(((prop.devid == host_devid) && (devid < SVM_MAX_DEV_AGENT_NUM)) ||
894	          ((prop.devid < SVM_MAX_DEV_AGENT_NUM) && (devid == host_devid)))) {
895	        svm_err("Only support h<->d. (register_va_devid=%u; access_devid=%u)\n", prop.devid, devid);
896	        return DRV_ERROR_PARA_ERROR;
897	    }
898	
899	    if (size == 0) {
900	        svm_err("Size is zero.\n");
901	        return DRV_ERROR_PARA_ERROR;
902	    }
903	
904	    return 0;
905	}
