907	static int svm_register_svm_to_peer(u64 va, u64 size, u32 devid, u64 *dst_va)
908	{
909	    void *va_handle = NULL;
910	    struct svm_prop prop;
911	    u64 aligned_size;
912	    int ret;
913	
914	    ret = svm_register_svm_to_peer_para_check(va, size, devid);
915	    if (ret != 0) {
916	        return ret;
917	    }
918	
919	    ret = svm_get_prop(va, &prop);
920	    if (ret != 0) {
921	        svm_err("Get prop failed. (va=0x%llx)\n", va);
922	        return DRV_ERROR_PARA_ERROR;
923	    }
924	
925	    ret = svm_share_get_src_aligned_size(prop.devid, prop.flag, va, size, &aligned_size);
926	    if (ret != 0) {
927	        svm_err("Get aligned size failed. (src_devid=%u; flag=0x%llx; va=0x%llx; size=0x%llx)\n", prop.devid, prop.flag,
928	                va, size);
929	        return DRV_ERROR_PARA_ERROR;
930	    }
931	
932	    ret = svm_share_check_dst_va_align(va, aligned_size, devid, va);
933	    if (ret != 0) {
934	        svm_err("Check dst va align failed. (va=0x%llx; aligned_size=0x%llx; devid=%u)\n", va, aligned_size, devid);
935	        return DRV_ERROR_PARA_ERROR;
936	    }
937	
938	    if ((va + size) > (prop.start + prop.size)) {
939	        svm_err("Size if out of bounds. (va=0x%llx; size=%d; align_size=0x%llx; prop start=0x%llx; prop size=0x%llx)\n",
940	                va, size, aligned_size, prop.start, prop.size);
941	        return DRV_ERROR_PARA_ERROR;
942	    }
943	
944	    va_handle = svm_handle_get(va);
945	    if (va_handle == NULL) { /* maybe va has been free after get prop */
946	        svm_err("Get va handle failed. (va=0x%llx)\n", va);
947	        return DRV_ERROR_PARA_ERROR;
948	    }
949	
950	    if (svm_flag_cap_is_support_vmm_unmap(prop.flag)) {
951	        ret = svm_vmm_register(va_handle, va, aligned_size, devid);
952	    } else {
953	        ret = svm_normal_register(va_handle, va, aligned_size, devid, &prop);
954	    }
955	
956	    svm_handle_put(va_handle);
957	    *dst_va = (ret == 0) ? va : *dst_va;
958	    return ret;
959	}
