1043	
1044	    ret = uda_get_udevid_by_devid_ex(src_devid, &src_udevid);
1045	    if (ret != DRV_ERROR_NONE) {
1046	        svm_err("Get src udev id failed. (ret=%d; src_devid=%u)\n", ret, src_devid);
1047	        return ret;
1048	    }
1049	
1050	    if (src_info->udevid != src_udevid) {
1051	        return 0;
