1057	            svm_err("Get seg prop failed. (ret=%d; va=0x%llx)\n", ret, src_info->va);
1058	            return ret;
1059	        }
1060	        src_info->tgid = src_prop.tgid;
1061	    } else {
1062	        src_info->tgid = (int)drvDeviceGetBareTgid();
1063	    }
1064	    svm_svmm_mod_seg_src_tgid(seg_handle, src_info->tgid);
1065	
1066	    svm_dst_va_pack(dst_devid, PROCESS_CP1, start, src_info->size, &dst_info);
1067	    ret = svm_smm_client_map(&dst_info, src_info, smm_flag);
1068	    if (ret != DRV_ERROR_NONE) {
1069	        svm_err("Restore register map failed. (ret=%d; dst_devid=%u; src_devid=%u; va=0x%llx; size=0x%llx)\n", ret,
1070	                dst_devid, src_devid, start, src_info->size);
1071	    }
1072	
1073	    return ret;
1074	}
1075	
1076	static int svm_register_svmm_insts_criu_restore(void *svmm_inst[], u32 num, u32 devid)
1077	{
1078	    u32 i;
1079	
1080	    for (i = 0; i < num; i++) {
1081	        if (svmm_inst[i] != NULL) {
1082	            struct svm_register_seg_criu_priv priv = {.src_devid = devid, .dst_devid = i};
1083	            int ret = svm_svmm_for_each_seg_handle(svmm_inst[i], svm_register_seg_criu_restore, &priv);
1084	            if (ret != DRV_ERROR_NONE) {
1085	                return ret;
1086	            }
1087	        }
1088	    }
1089	
1090	    return DRV_ERROR_NONE;
1091	}
1092	
1093	static int svm_register_criu_restore(u32 devid, void *data)
1094	{
1095	    struct list_head *node = NULL;
1096	    struct list_head *tmp = NULL;
1097	    int ret = DRV_ERROR_NONE;
1098	
1099	    SVM_UNUSED(data);
1100	
1101	    (void)pthread_mutex_lock(&register_mutex);
1102	    list_for_each_safe(node, tmp, &register_head)
1103	    {
1104	        struct svm_register_node *register_node = list_entry(node, struct svm_register_node, node);
1105	        ret = svm_register_svmm_insts_criu_restore(register_node->svmm_inst, SVM_MAX_DEV_NUM, devid);
1106	        if (ret != DRV_ERROR_NONE) {
1107	            break;
1108	        }
