170	static int vmm_check_map_route(drv_mem_handle_t *handle, u32 map_route)
171	{
172	    struct svm_global_va src_va = {0};
173	    u64 update_va, ex_info, offset;
174	    u32 src_sdid = 0; /* addr trans use mem_id, not use sdid */
175	    u32 src_mem_id;
176	    int ret;
177	
178	    if ((map_route != MEM_MAP_DEFAULT_PATH) && (map_route != MEM_MAP_UB_ONE_PORT_PATH) &&
179	        (map_route != MEM_MAP_UB_MULTI_PORT_PATH)) {
180	        svm_debug("Map route not support. (map_route=%u)\n", map_route);
181	        return DRV_ERROR_NOT_EXIST;
182	    }
183	
184	    ret = svm_casm_get_src_va_ex(handle->devid, handle->key, &src_va, &update_va, &ex_info);
185	    if (ret != DRV_ERROR_NONE) {
186	        svm_err("Get src va failed. (key=%llu)\n", handle->key);
187	        return ret;
188	    }
189	    if (update_va == 0) {
190	        svm_debug("Not ubmem map. (key=%llu)\n", handle->key);
191	        return DRV_ERROR_NOT_EXIST;
192	    }
193	    svm_ub_va_to_mem_id_and_offset(update_va, &src_mem_id, &offset);
194	
195	    return ubmemMapRouteCheck(handle->devid, src_sdid, src_mem_id, map_route);
