324	#define SVM_NUMA_NO_NODE 0xFFFFFFFFU
325	static int vmm_prop_check(const struct drv_mem_prop *prop, bool is_from_create)
326	{
327	    if (prop == NULL) {
328	        svm_err("Prop is null.\n");
329	        return DRV_ERROR_INVALID_VALUE;
330	    }
331	
332	    if (prop->side >= MEM_MAX_SIDE) {
333	        svm_err("Invalid side type. (side=%u)\n", prop->side);
334	        return DRV_ERROR_INVALID_VALUE;
335	    }
336	
337	    if ((prop->side == MEM_DEV_SIDE) && (prop->devid >= SVM_MAX_DEV_AGENT_NUM)) {
338	        svm_err("Invalid side devid. (side=%u; devid=%u)\n", prop->side, prop->devid);
339	        return DRV_ERROR_INVALID_VALUE;
340	    }
341	
342	    if (prop->side == MEM_HOST_SIDE) {
343	        if ((is_from_create) && (prop->devid != 0)) {
344	            svm_run_info("Devid must be 0 in host side.\n");
345	            return DRV_ERROR_NOT_SUPPORT;
346	        } else if ((is_from_create == false) && (prop->devid > svm_get_host_devid())) {
347	            svm_err("Devid must be less than host devid. (devid=%u)\n", prop->devid);
348	            return DRV_ERROR_INVALID_VALUE;
349	        }
350	    }
351	
352	    if ((prop->side == MEM_HOST_NUMA_SIDE) && (prop->devid >= SVM_MALLOC_NUMA_NO_NODE) &&
353	        (prop->devid != SVM_NUMA_NO_NODE)) {
354	        svm_err("Invalid numa id. (numa_id=%u)\n", prop->devid);
355	        return DRV_ERROR_PARA_ERROR;
356	    }
357	
358	    if (prop->pg_type >= MEM_MAX_PAGE_TYPE) {
359	        svm_err("Invalid page type. (pg_type=%u)\n", prop->pg_type);
360	        return DRV_ERROR_INVALID_VALUE;
361	    }
362	
363	    if (prop->mem_type >= MEM_MAX_TYPE) {
364	        svm_err("Invalid mem type. (mem_type=%u)\n", prop->mem_type);
365	        return DRV_ERROR_INVALID_VALUE;
366	    }
367	
368	    if (prop->reserve != 0) {
369	        svm_err("prop reserve should be zero.\n");
370	        return DRV_ERROR_INVALID_VALUE;
371	    }
372	
373	    if (prop->pg_type == MEM_GIANT_PAGE_TYPE) {
374	        if (prop->mem_type == MEM_TS_DDR_TYPE) {
375	            svm_run_info("Giant page not support ts_ddr.\n");
376	            return DRV_ERROR_NOT_SUPPORT;
377	        }
378	        if (prop->side != MEM_DEV_SIDE) {
379	            svm_run_info("Giant page not support host.\n");
380	            return DRV_ERROR_NOT_SUPPORT;
381	        }
382	    }
383	
384	    return DRV_ERROR_NONE;
385	}
