387	static int vmm_get_granularity(drv_mem_granularity_options option, enum drv_mem_pg_type pg_type, u32 module_id,
388	                               u32 devid, size_t *gran)
389	{
390	    size_t granularity = vmm_get_granularity_by_pg_type(pg_type);
391	    u32 host_devid = svm_get_host_devid();
392	    u64 npage_size;
393	    int ret;
394	
395	    ret = svm_dbi_query_npage_size(host_devid, &npage_size);
396	    if (ret != DRV_ERROR_NONE) {
397	        svm_err("Dbi query failed. (devid=%u; ret=%d)\n", host_devid, ret);
398	        return ret;
399	    }
400	    granularity = ((pg_type == MEM_NORMAL_PAGE_TYPE) && (option == MEM_ALLOC_GRANULARITY_MINIMUM) &&
401	                   (devid == host_devid) && (module_id == RUNTIME_MODULE_ID)) ?
402	                      npage_size :
403	                      granularity;
404	    *gran = granularity;
405	    return DRV_ERROR_NONE;
406	}
