408	drvError_t halMemGetAllocationGranularity(const struct drv_mem_prop *prop, drv_mem_granularity_options option,
409	                                          size_t *granularity)
410	{
411	    drvError_t ret;
412	
413	    if (option >= MEM_ALLOC_GRANULARITY_INVALID) {
414	        return DRV_ERROR_NOT_SUPPORT;
415	    }
416	
417	    if (granularity == NULL) {
418	        svm_err("granularity is NULL.\n");
419	        return DRV_ERROR_INVALID_VALUE;
420	    }
421	
422	    ret = vmm_prop_check(prop, false);
423	    if (ret != 0) {
424	        return ret;
425	    }
426	
427	    ret = svm_master_init();
428	    if (ret != DRV_ERROR_NONE) {
429	        svm_err("Svm master init failed. (ret=%d)\n", ret);
430	        return ret;
431	    }
432	
433	    ret = vmm_get_granularity(option, prop->pg_type, prop->module_id, prop->devid, granularity);
434	    svm_debug(
435	        "MemGetAllocationGranularity exit. (ret=%d; option=%u; pg_type=%u; module_id=%u; devid=%u; granularity=%llu)\n",
436	        ret, (u32)option, prop->pg_type, prop->module_id, prop->devid, (u64)(*granularity));
437	    return ret;
438	}
