440	static void vmm_recycle_single(void *svmm_inst, u32 udevid)
441	{
442	    u32 recyle_num = 0;
443	
444	    while (1) {
445	        drv_mem_handle_t *handle = NULL;
446	        struct svm_global_va src_info;
447	        struct svm_dst_va dst_info;
448	        u64 va, svm_flag;
449	        u32 smm_flag = 0;
450	        u32 devid;
451	        int ret;
452	
453	        src_info.udevid = udevid;
454	        ret = svm_svmm_get_seg_by_src_udevid(svmm_inst, &devid, &va, &svm_flag, &src_info);
455	        if (ret != 0) {
456	            break;
457	        }
458	
459	        handle = (drv_mem_handle_t *)(uintptr_t)src_info.va;
460	        vmm_restore_real_src_va(&src_info);
461	        vmm_recycle_pa_handle(handle);
462	
463	        svm_dst_va_pack(devid, PROCESS_CP1, va, src_info.size, &dst_info);
464	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
465	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info.size, true);
466	        recyle_num++;
467	    }
468	
469	    if (recyle_num > 0) {
470	        svm_info("Recycle success. (udevid=%u; recyle_num=%u)\n", udevid, recyle_num);
471	    }
472	}
