477	    u32 devid = *(u32 *)priv;
478	
479	    SVM_UNUSED(start);
480	    SVM_UNUSED(src_info);
481	
482	    if ((access_node == NULL) || (devid == access_node->owner_devid)) {
483	        return 0;
484	    }
485	
486	    (void)pthread_rwlock_wrlock(&access_node->rwlock);
487	    if (access_node->access_type[devid] != MEM_ACCESS_TYPE_NONE) {
488	        vmm_access_single_do_unmap(access_node, devid);
489	    }
490	    (void)pthread_rwlock_unlock(&access_node->rwlock);
491	
492	    return 0;
493	}
