543	static int vmm_svmm_release(void *priv, bool force)
544	{
545	    struct svm_vmm_node *vmm_node = (struct svm_vmm_node *)priv;
546	    void *svmm_inst = NULL;
547	    u32 recyle_num = 0;
548	
549	    if (vmm_node == NULL) {
550	        return 0;
551	    }
552	
553	    svmm_inst = vmm_node->svmm_inst;
554	    if (svmm_inst == NULL) { /* alloc failed, to free */
555	        svm_ua_free(vmm_node);
556	        return 0;
557	    }
558	
559	    while (1) {
560	        struct svm_global_va src_info;
561	        struct svm_dst_va dst_info;
562	        u64 va, svm_flag;
563	        u32 devid;
564	        u32 smm_flag = 0;
565	        int ret;
566	
567	        ret = svm_svmm_get_first_seg(svmm_inst, &devid, &va, &svm_flag, &src_info);
568	        if (ret != 0) {
569	            break;
570	        }
571	
572	        if (force == false) {
573	            return DRV_ERROR_BUSY;
574	        }
575	
576	        svm_dst_va_pack(devid, PROCESS_CP1, va, src_info.size, &dst_info);
577	        vmm_restore_real_src_va(&src_info);
578	
579	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
580	        (void)svm_svmm_del_seg(svmm_inst, devid, va, src_info.size, true);
581	        recyle_num++;
582	    }
583	
584	    if (recyle_num > 0) {
585	        u64 svmma_start, svmma_size, svm_flag;
586	        svm_svmm_parse_inst_info(svmm_inst, &svmma_start, &svmma_size, &svm_flag);
587	        svm_info("Force release success. (va=0x%llx; size=0x%llx; recyle_num=%u)\n", svmma_start, svmma_size,
588	                 recyle_num);
589	    }
590	
591	    svm_vmm_svmm_destroy(vmm_node);
592	
593	    return 0;
594	}
