596	static int vmm_get_prop(void *priv, u64 va, struct svm_prop *prop)
597	{
598	    struct svm_vmm_node *vmm_node = (struct svm_vmm_node *)priv;
599	    void *svmm_inst = NULL;
600	    struct svm_global_va src_info;
601	    u64 svm_flag;
602	    u32 devid;
603	    int ret;
604	
605	    if (vmm_node == NULL) {
606	        return DRV_ERROR_INVALID_VALUE;
607	    }
608	
609	    svmm_inst = vmm_node->svmm_inst;
610	    if (svmm_inst == NULL) {
611	        return DRV_ERROR_INVALID_VALUE;
612	    }
613	
614	    ret = svm_svmm_get_seg_by_va(svmm_inst, &devid, &va, &svm_flag, &src_info);
615	    if (ret != 0) { /* not map, use vmm va prop */
616	        prop->devid = SVM_INVALID_DEVID;
617	        prop->tgid = 0;
618	        svm_svmm_parse_inst_info(svmm_inst, &prop->start, &prop->size, &prop->flag);
619	        prop->aligned_size = prop->size;
620	        ret = 0;
621	    } else {
622	        prop->devid = devid;
623	        prop->tgid = src_info.tgid; /* should use map dst tgid, fixed it later */
624	        prop->flag = svm_flag;
625	        prop->start = va;
626	        prop->size = src_info.size;
627	        ret = svm_get_aligned_size(prop->devid, prop->flag, prop->size, &prop->aligned_size);
628	    }
629	
630	    return ret;
631	}
