670	static int _vmm_create_svmm_inst(void *va_handle, u64 start, u64 size, u64 svm_flag)
671	{
672	    struct svm_vmm_node *vmm_node = NULL;
673	    void *svmm_inst = NULL;
674	
675	    vmm_node = (struct svm_vmm_node *)svm_ua_calloc(1, sizeof(*vmm_node));
676	    if (vmm_node == NULL) {
677	        /* must set priv, to free the va */
678	        (void)svm_set_priv(va_handle, NULL, &vmm_priv_ops);
679	        svm_err("Malloc failed. (va=0x%llx)\n", start);
680	        return DRV_ERROR_OUT_OF_MEMORY;
681	    }
682	
683	    svmm_inst = svm_svmm_create_inst(start, size, SVMM_NON_OVERLAP, svm_flag);
684	    if (svmm_inst == NULL) {
685	        /* must set priv, to free the va, free vmm_node in release */
686	        (void)svm_set_priv(va_handle, vmm_node, &vmm_priv_ops);
687	        svm_err("Create svmm failed. (start=%llx)\n", start);
688	        return DRV_ERROR_OUT_OF_MEMORY;
689	    }
690	
691	    vmm_node->head.type = SVM_SHARE_TYPE_VMM;
692	    vmm_node->svmm_inst = svmm_inst;
693	
694	    (void)svm_set_priv(va_handle, vmm_node, &vmm_priv_ops);
695	
696	    return 0;
697	}
