715	static int vmm_malloc_va(u64 align, void **va, u64 size, u64 flag)
716	{
717	    struct svm_malloc_location location;
718	    u64 start, svm_flag = 0;
719	    int ret;
720	
721	    svm_flag |= SVM_FLAG_CAP_VMM_VA_FREE;
722	    svm_flag |= SVM_FLAG_CAP_VMM_MAP;
723	    svm_flag |= SVM_FLAG_ATTR_VA_ONLY;
724	    svm_flag |= SVM_FLAG_MUST_WITH_PRIV;
725	    svm_flag |= SVM_FLAG_BY_PASS_CACHE;
726	    svm_flag_set_module_id(&svm_flag, SVM_FLAG_INVALID_MODULE_ID);
727	
728	    start = (u64)(uintptr_t)(*va);
729	    if (start != 0) {
730	        svm_flag |= SVM_FLAG_ATTR_SPACIFIED_VA;
731	        if (svm_is_in_dcache_va_range(start, size)) {
732	            svm_flag |= SVM_FLAG_ATTR_VA_WITHOUT_MASTER;
733	        }
734	    }
735	
736	    if ((flag & MEM_RSV_TYPE_DEVICE_SHARE) != 0) {
737	        svm_flag |= SVM_FLAG_ATTR_VA_WITHOUT_MASTER;
738	    }
739	
740	    svm_malloc_location_pack(SVM_INVALID_DEVID, SVM_MALLOC_NUMA_NO_NODE, &location);
741	
742	    ret = svm_malloc(&start, size, align, svm_flag, &location);
743	    if (ret != 0) {
744	        return ret;
745	    }
746	
747	    ret = vmm_create_svmm_inst(start, size, svm_flag);
748	    if (ret != 0) {
749	        (void)svm_free(start);
750	        return ret;
751	    }
752	
753	    (*va) = (void *)(uintptr_t)start;
754	
755	    return 0;
756	}
