758	static int vmm_free_va(void *va)
759	{
760	    struct svm_prop prop;
761	    u64 start = (u64)(uintptr_t)va;
762	    int ret;
763	
764	    ret = svm_get_prop(start, &prop);
765	    if (ret != 0) {
766	        svm_err("Get prop failed. (start=%llx)\n", start);
767	        svm_report_addr_not_allocated("halMemAddressFree", "ptr", start);
768	        return ret;
769	    }
770	
771	    if (!svm_flag_cap_is_support_vmm_va_free(prop.flag)) {
772	        svm_err("Addr cap is not support vmm va free. (va=0x%llx)\n", start);
773	        return DRV_ERROR_INVALID_VALUE;
774	    }
775	
776	    ret = svm_free(start);
777	    return (ret == DRV_ERROR_CLIENT_BUSY) ? DRV_ERROR_BUSY : ret;
778	}
