780	static int vmm_address_reserve_para_check(void **ptr, size_t size, size_t alignment, void *addr, u32 pg_type)
781	{
782	    u64 specify_va = (u64)(uintptr_t)addr;
783	
784	    if (ptr == NULL) {
785	        svm_err("Ptr is null.\n");
786	        return DRV_ERROR_INVALID_VALUE;
787	    }
788	
789	    if (size == 0) {
790	        svm_err("size is zero.\n");
791	        return DRV_ERROR_INVALID_VALUE;
792	    }
793	
794	    if ((specify_va != 0) && ((specify_va != svm_align_up(specify_va, VMM_ALLOC_RECOMMENDED_GRANULARITY)) ||
795	                              (svm_is_valid_range(specify_va, size) == false))) {
796	        svm_err("Specified addr not aligned up with recommended granularity or mix range. (addr=0x%llx; size=0x%lx)\n",
797	                specify_va, size);
798	        if (specify_va != svm_align_up(specify_va, VMM_ALLOC_RECOMMENDED_GRANULARITY)) {
799	            svm_report_addr_not_aligned("halMemAddressReserve", "addr", specify_va, VMM_ALLOC_RECOMMENDED_GRANULARITY);
800	        }
801	        return DRV_ERROR_INVALID_VALUE;
802	    }
803	
804	    /* reserved para, verify by zero for subsequent compatibility */
805	    if (alignment != 0) {
806	        svm_report_para_only_zero("halMemAddressReserve", "alignment", (u64)alignment);
807	        svm_err("Alignment should be zero.\n");
808	        return DRV_ERROR_INVALID_VALUE;
809	    }
810	
811	    if (pg_type >= MEM_MAX_PAGE_TYPE) {
812	        svm_err("Invalid pg type. (pg_type=%u)\n", pg_type);
813	        return DRV_ERROR_INVALID_VALUE;
814	    }
815	
816	    if ((specify_va != 0) && (svm_is_in_dcache_va_range(specify_va, size) && (pg_type > MEM_HUGE_PAGE_TYPE))) {
817	        svm_err("Dcache page_type invalid. (addr=0x%llx; page_type=%u)\n", specify_va, pg_type);
818	        return DRV_ERROR_INVALID_VALUE;
819	    }
820	
821	    return 0;
822	}
823	
824	static u64 vmm_get_va_align(u32 pg_type)
825	{
826	    static u64 pg_type_to_align[MEM_MAX_PAGE_TYPE] = {[MEM_NORMAL_PAGE_TYPE] = VMM_ALLOC_GRANULARITY_2M,
827	                                                      [MEM_HUGE_PAGE_TYPE] = VMM_ALLOC_GRANULARITY_2M,
828	                                                      [MEM_GIANT_PAGE_TYPE] = VMM_ALLOC_GRANULARITY_1G};
829	
830	    return pg_type_to_align[pg_type];
831	}
832	
833	drvError_t halMemAddressReserve(void **ptr, size_t size, size_t alignment, void *addr, uint64_t flag)
834	{
835	    void *malloc_va = addr; /* Application for a specified address */
836	    u64 len = (u64)size;
837	    u32 pg_type;
838	    int ret;
839	
840	    pg_type = (u32)(flag & 0xFF); /* 0xFF, pgtype mask */
841	    ret = vmm_address_reserve_para_check(ptr, size, alignment, addr, pg_type);
842	    if (ret != 0) {
843	        return (drvError_t)ret;
844	    }
845	
846	    if (!svm_is_in_dcache_va_range((u64)malloc_va, size)) { /* Dcache range size isn't aligned by GB */
847	        /* Inheriting from the old version, the user wants to alloc 1GB aligned va,
848	           but the passed flag is MEM_HUGE_PAGE_TYPE. */
849	        if (size >= SVM_BYTES_PER_GB) {
850	            pg_type = MEM_GIANT_PAGE_TYPE;
851	        }
852	
853	        if (((flag & MEM_RSV_TYPE_DEVICE_SHARE) != 0) || (size >= SVM_VA_RESERVE_ALIGN)) {
854	            len = svm_align_up((u64)size, SVM_VA_RESERVE_ALIGN);
855	        }
856	    }
857	
858	    svm_use_pipeline();
859	    ret = vmm_malloc_va(vmm_get_va_align(pg_type), &malloc_va, len, flag);
860	    svm_unuse_pipeline();
861	
862	    if (ret == DRV_ERROR_NONE) {
863	        svm_debug("Vmm reserve. (va=0x%llx; size=%llu; flag=0x%llx; pg_type=%u)\n", (u64)(uintptr_t)malloc_va, size,
864	                  flag, pg_type);
865	    }
866	
867	    *ptr = (ret == 0) ? malloc_va : *ptr;
868	    return (drvError_t)ret;
869	}
870	
871	drvError_t halMemAddressFree(void *ptr)
872	{
873	    drvError_t ret;
874	
875	    if (ptr == NULL) {
876	        svm_err("Ptr is null.\n");
877	        return DRV_ERROR_INVALID_VALUE;
878	    }
879	
880	    svm_debug("Vmm free. (Va=0x%llx)\n", (u64)(uintptr_t)ptr);
881	    svm_use_pipeline();
882	    ret = vmm_free_va(ptr);
883	    svm_unuse_pipeline();
884	
885	    if (ret != 0) {
886	        svm_err("Vmm free va failed. (ret=%d; ptr=0x%llx)\n", ret, (u64)(uintptr_t)ptr);
887	    }
888	
889	    return (drvError_t)ret;
890	}
