928	static int vmm_malloc_pa(drv_mem_handle_t **handle, u64 size, const struct drv_mem_prop *prop)
929	{
930	    u32 module_id = (prop->module_id == UNKNOWN_MODULE_ID) ? ASCENDCL_MODULE_ID : prop->module_id;
931	    u32 numa_id = vmm_get_numa_id(prop->side, prop->devid);
932	    u32 pg_type = vmm_get_real_pg_type(prop->pg_type, module_id, size);
933	    u32 devid = prop->devid;
934	    u64 start = 0;
935	    u64 svm_flag = 0;
936	    int ret;
937	
938	    if ((prop->mem_type == MEM_P2P_HBM_TYPE) || (prop->mem_type == MEM_P2P_DDR_TYPE)) {
939	        svm_flag |= SVM_FLAG_ATTR_PA_P2P;
940	    }
941	    if ((prop->side == MEM_HOST_SIDE) || (prop->side == MEM_HOST_NUMA_SIDE)) {
942	        devid = svm_get_host_devid();
943	    }
944	
945	    svm_flag |= SVM_FLAG_CAP_VMM_PA_FREE;
946	    svm_flag |= SVM_FLAG_CAP_VMM_EXPORT;
947	    svm_flag |= SVM_FLAG_BY_PASS_CACHE;
948	    svm_flag |= (pg_type == MEM_GIANT_PAGE_TYPE) ? SVM_FLAG_ATTR_PA_GPAGE :
949	                                                   ((pg_type == MEM_NORMAL_PAGE_TYPE) ? 0 : SVM_FLAG_ATTR_PA_HPAGE);
950	    svm_flag |= (vmm_is_need_pa_continuous(devid, prop->side, pg_type) ? SVM_FLAG_ATTR_PA_CONTIGUOUS : 0);
951	
952	    ret = svm_module_mem_malloc(devid, numa_id, svm_flag, &start, size, module_id);
953	    if (ret != 0) {
954	        svm_no_err_if((ret == DRV_ERROR_OUT_OF_MEMORY),
955	                      "Module mem malloc not success. (ret=%d; size=%llu; devid=%u)\n", ret, size, devid);
956	        return ret;
957	    }
958	
959	    *handle = vmm_normal_handle_create(devid, start, prop);
960	    if (*handle == NULL) {
961	        svm_module_mem_free(devid, svm_flag, start, size, prop->module_id);
962	        return DRV_ERROR_OUT_OF_MEMORY;
963	    }
964	
965	    return 0;
966	}
967	
968	static int vmm_free_pa(drv_mem_handle_t *handle)
969	{
970	    struct svm_prop prop;
971	    u64 start = handle->va;
972	    int ret;
973	
974	    ret = svm_get_prop(start, &prop);
975	    if (ret != 0) {
976	        /* The log cannot be modified, because in the failure mode library. */
977	        svm_err("Vmm release find handle failed. (start=0x%llx)\n", start);
978	        return ret;
979	    }
980	
981	    if (!svm_flag_cap_is_support_vmm_pa_free(prop.flag)) {
982	        svm_err("Addr cap is not support vmm pa free. (start=0x%llx)\n", start);
983	        return DRV_ERROR_INVALID_VALUE;
984	    }
985	
986	    if (svm_atomic64_sub(&handle->ref, 1ULL) > 0ULL) {
987	        return 0;
988	    }
989	
990	    ret = svm_module_mem_free(prop.devid, prop.flag, start, prop.size, svm_flag_get_module_id(prop.flag));
991	    if (ret != 0) {
992	        svm_atomic64_inc(&handle->ref);
993	        return ret;
994	    }
995	
996	    vmm_normal_handle_destroy(handle);
997	
998	    return 0;
999	}
