1021	drvError_t halMemCreateInner(drv_mem_handle_t **handle, size_t size, const struct drv_mem_prop *prop, uint64_t flag);
1022	drvError_t halMemCreateInner(drv_mem_handle_t **handle, size_t size, const struct drv_mem_prop *prop, uint64_t flag)
1023	{
1024	    size_t granularity;
1025	    u32 module_id;
1026	    u32 devid;
1027	    int ret;
1028	
1029	    if (handle == NULL) {
1030	        svm_err("Handle is null.\n");
1031	        return DRV_ERROR_INVALID_VALUE;
1032	    }
1033	
1034	    /* reserved para, verify by zero for subsequent compatibility */
1035	    if (flag != 0) {
1036	        svm_err("Flag should be zero.\n");
1037	        return DRV_ERROR_INVALID_VALUE;
1038	    }
1039	
1040	    ret = svm_master_init();
1041	    if (ret != DRV_ERROR_NONE) {
1042	        svm_err("Svm master init failed. (ret=%d)\n", ret);
1043	        return ret;
1044	    }
1045	
1046	    ret = vmm_prop_check(prop, true);
1047	    if (ret != 0) {
1048	        return (drvError_t)ret;
1049	    }
1050	
1051	    granularity = vmm_get_create_granularity(prop->pg_type, prop->module_id, size);
1052	    if ((size == 0) || ((size % granularity) != 0)) {
1053	        /* The log cannot be modified, because in the failure mode library. */
1054	        svm_err("Size is invalid. (size=%llu; granularity=%llu; side=%u; pg_type=%u; module_id=%u)\n", (u64)size,
1055	                (u64)granularity, prop->side, prop->pg_type, prop->module_id);
1056	        return DRV_ERROR_INVALID_VALUE;
1057	    }
1058	
1059	    svm_use_pipeline();
1060	    ret = vmm_malloc_pa(handle, (u64)size, prop);
1061	    svm_unuse_pipeline();
1062	    if (ret == DRV_ERROR_OUT_OF_MEMORY) {
1063	        module_id = (prop->module_id >= MAX_MODULE_ID) ? UNKNOWN_MODULE_ID : prop->module_id;
1064	        devid = ((prop->side == MEM_HOST_SIDE) || (prop->side == MEM_HOST_NUMA_SIDE)) ? svm_get_host_devid() :
1065	                                                                                        prop->devid;
1066	        svm_report_oom(size, halGetMemModuleName(module_id), devid);
1067	    }
1068	    if (ret == 0) {
1069	        svm_debug("Vmm create. (size=%llu; side=%d; devid=%u; module_id=%u; pg_type=%u; mem_type=%u; handle_va=0x%llx)"
1070	                  "\n",
1071	                  size, prop->side, prop->devid, prop->module_id, prop->pg_type, prop->mem_type, (*handle)->va);
1072	    }
1073	
1074	    return (drvError_t)ret;
1075	}
