1299	static int _vmm_single_app_mmap(void *va_handle, u64 va, u64 size, struct svm_prop *src_prop, drv_mem_handle_t *handle)
1300	{
1301	    struct svm_dst_va dst_info;
1302	    struct svm_global_va src_info;
1303	    void *svmm_inst = NULL;
1304	    void *seg_handle = NULL;
1305	    u64 svm_flag = 0;
1306	    u32 smm_flag = 0;
1307	    int ret;
1308	
1309	    svmm_inst = vmm_get_svmm(va_handle);
1310	    if (svmm_inst == NULL) { /* vmm map addr first prefetch */
1311	        svm_err("Get svmm inst failed. (va=%llx)\n", va);
1312	        return DRV_ERROR_PARA_ERROR;
1313	    }
1314	
1315	    svm_global_va_pack(0, src_prop->tgid, src_prop->start, size, &src_info);
1316	    ret = uda_get_udevid_by_devid_ex(src_prop->devid, &src_info.udevid);
1317	    if (ret != DRV_ERROR_NONE) {
1318	        svm_err("Get udevid failed. (devid=%u; ret=%d)\n", src_prop->devid, ret);
1319	        return ret;
1320	    }
1321	
1322	    svm_flag = vmm_get_single_app_mmap_svm_flag(va, size, src_prop->flag);
1323	    src_info.va = (u64)(uintptr_t)handle; /* use va to store handle, get real va from handle */
1324	    ret = svm_svmm_add_seg(svmm_inst, src_prop->devid, va, svm_flag, &src_info);
1325	    if (ret != 0) {
1326	        svm_err("Add seg failed. (devid=%u; va=%llx; size=%llx)\n", src_prop->devid, va, size);
1327	        return ret;
1328	    }
1329	
1330	    src_info.va = src_prop->start; /* map use real va */
1331	
1332	    svm_dst_va_pack(src_prop->devid, PROCESS_CP1, va, size, &dst_info);
1333	    ret = svm_smm_client_map(&dst_info, &src_info, smm_flag);
1334	    if (ret != 0) {
1335	        svm_err("Smm map failed. (devid=%u; va=%llx; size=%llx)\n", src_prop->devid, va, size);
1336	        (void)svm_svmm_del_seg(svmm_inst, src_prop->devid, va, size, true);
1337	        return ret;
1338	    }
1339	
1340	    seg_handle = svm_svmm_seg_handle_get(svmm_inst, va);
1341	    if (seg_handle == NULL) {
1342	        svm_err("Get seg handle failed. (va=0x%llx)\n", va);
1343	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
1344	        (void)svm_svmm_del_seg(svmm_inst, src_prop->devid, va, size, true);
1345	        return DRV_ERROR_PARA_ERROR;
1346	    }
1347	
1348	    ret = vmm_ops_post_map(seg_handle, src_prop->devid, va, svm_flag, &src_info);
1349	    svm_svmm_seg_handle_put(seg_handle);
1350	    if (ret != 0) {
1351	        svm_err("Post map failed. (devid=%u; va=%llx; size=%llx)\n", src_prop->devid, va, size);
1352	        (void)svm_smm_client_unmap(&dst_info, &src_info, smm_flag);
1353	        (void)svm_svmm_del_seg(svmm_inst, src_prop->devid, va, size, true);
1354	        return ret;
1355	    }
1356	
1357	    return 0;
1358	}
