1443	        return DRV_ERROR_PARA_ERROR;
1444	    }
1445	
1446	    src_info.udevid = SVM_INVALID_UDEVID;
1447	    ret = svm_svmm_get_seg(svmm_inst, &devid, &start, &svm_flag, &src_info);
