1591	    src_info.va = (u64)(uintptr_t)handle; /* cross app mmap src info is not used, use va to store handle */
1592	    src_info.size = size;
1593	    ret = svm_svmm_add_seg(svmm_inst, (u32)dst_devid, va, svm_flag, &src_info);
1594	    if (ret != 0) {
1595	        svm_err("Add seg failed. (devid=%u; va=%llx; size=%llx)\n", dst_devid, va, size);
1596	        return ret;
1597	    }
1598	
1599	    ret = svm_casm_mem_map((u32)dst_devid, va, size, key, casm_flag);
1600	    if (ret != 0) {
1601	        svm_err("Casm map failed. (devid=%u; va=%llx; size=%llx)\n", dst_devid, va, size);
1602	        (void)svm_svmm_del_seg(svmm_inst, (u32)dst_devid, va, size, true);
1603	        return ret;
1604	    }
1605	
1606	    return 0;
1607	}
