1684	static int vmm_mmap(void *va, u64 size, drv_mem_handle_t *handle, u64 offset)
1685	{
1686	    struct svm_prop prop;
1687	    u64 start = (u64)(uintptr_t)va;
1688	    int ret;
1689	
1690	    ret = svm_get_prop(start, &prop);
1691	    if (ret != 0) {
1692	        svm_err("Get prop failed. (start=%llx)\n", start);
1693	        svm_report_addr_not_allocated("halMemMap", "ptr", start);
1694	        return ret;
1695	    }
1696	
1697	    if (!svm_flag_cap_is_support_vmm_map(prop.flag)) {
1698	        svm_err("Addr cap is not support vmm map. (start=0x%llx)\n", start);
1699	        return DRV_ERROR_PARA_ERROR;
1700	    }
1701	
1702	    if (handle->type == SVM_VMM_HANDLE_IMPORT_TYPE) {
1703	        ret = vmm_cross_app_mmap(start, size, handle, offset);
1704	    } else {
1705	        ret = vmm_single_app_mmap(start, size, handle, offset);
1706	    }
1707	
1708	    if (ret == 0) {
1709	        svm_atomic64_inc(&handle->ref);
1710	    }
1711	
1712	    return ret;
1713	}
