1715	static int vmm_munmap(void *va)
1716	{
1717	    struct svm_prop prop;
1718	    u64 start = (u64)(uintptr_t)va;
1719	    int ret;
1720	
1721	    ret = svm_get_prop(start, &prop);
1722	    if (ret != 0) {
1723	        /* The log cannot be modified, because in the failure mode library. */
1724	        svm_err("Vmm unmap find addr failed. (start=0x%llx)\n", start);
1725	        svm_report_addr_not_allocated("halMemUnmap", "ptr", start);
1726	        return ret;
1727	    }
1728	
1729	    if (svm_flag_cap_is_support_vmm_unmap(prop.flag)) {
1730	        return vmm_single_app_unmap(prop.devid, start, prop.aligned_size);
1731	    } else if (svm_flag_cap_is_support_vmm_ipc_unmap(prop.flag)) {
1732	        return vmm_cross_app_unmap(prop.devid, start, prop.aligned_size);
1733	    } else {
1734	        /* The log cannot be modified, because in the failure mode library. */
1735	        svm_err("Addr can not unmap. (va=0x%llx)\n", start);
1736	        return DRV_ERROR_PARA_ERROR;
1737	    }
1738	}
