1740	static void vmm_report_mmap_align_error(void *ptr, size_t size, drv_mem_handle_t *handle)
1741	{
1742	    u64 page_size, dst_npage_size;
1743	    int ret;
1744	
1745	    ret = svm_dbi_query_npage_size(handle->devid, &dst_npage_size);
1746	    if (handle->src_prop_valid == 1) {
1747	        page_size = vmm_get_real_pg_size(handle->src_prop.pg_type, handle->src_prop.module_id, size);
1748	        if ((ret == DRV_ERROR_NONE) && (dst_npage_size > page_size)) {
1749	            page_size = dst_npage_size;
1750	        }
1751	    } else {
1752	        if (ret != DRV_ERROR_NONE) {
1753	            return;
1754	        }
1755	        page_size = dst_npage_size;
1756	    }
1757	
1758	    if (!SVM_IS_ALIGNED((u64)(uintptr_t)ptr, page_size)) {
1759	        svm_report_addr_not_aligned("halMemMap", "ptr", (u64)(uintptr_t)ptr, page_size);
1760	    } else if (!SVM_IS_ALIGNED(size, page_size)) {
1761	        svm_report_size_not_aligned("halMemMap", "size", size, page_size);
1762	    }
1763	}
1764	
1765	static int vmm_mmap_para_check(void *ptr, size_t size, size_t offset, drv_mem_handle_t *handle, uint64_t flag)
1766	{
1767	    int ret;
1768	    u64 aligned, page_size;
1769	
1770	    if ((ptr == NULL) || (handle == NULL) || (size == 0)) {
1771	        svm_err("Invalid para. (ptr=%u; handle=%u; size=%u)\n", (ptr == NULL), (handle == NULL), size);
1772	        return DRV_ERROR_INVALID_VALUE;
1773	    }
1774	
1775	    /* reserved para, verify by zero for subsequent compatibility */
1776	    if (offset != 0) {
1777	        svm_err("Offset should be zero.\n");
1778	        return DRV_ERROR_INVALID_VALUE;
1779	    }
1780	
1781	    /* reserved para, verify by zero for subsequent compatibility */
1782	    if (flag != 0) {
1783	        svm_err("Flag should be zero.\n");
1784	        return DRV_ERROR_INVALID_VALUE;
1785	    }
1786	
1787	    ret = svm_share_get_dst_align((u64)(uintptr_t)ptr, size, handle->devid, &aligned);
1788	    if (ret != 0) {
1789	        svm_err("Not aligned. (ptr=0x%llx; size=%llu; devid=%u)\n", (u64)(uintptr_t)ptr, (u64)size, handle->devid);
1790	        vmm_report_mmap_align_error(ptr, size, handle);
1791	        return DRV_ERROR_PARA_ERROR;
1792	    }
1793	
1794	    if (handle->src_prop_valid == 1) {
1795	        page_size = vmm_get_real_pg_size(handle->src_prop.pg_type, handle->src_prop.module_id, size);
1796	        if (page_size > aligned) {
1797	            svm_err("Not aligned. (ptr=0x%llx; pg_type=%u; size=%llu; module_id=%u; page_size=%llu; aligned=%llu)\n",
1798	                    (u64)(uintptr_t)ptr, handle->src_prop.pg_type, (u64)size, handle->src_prop.module_id, page_size,
1799	                    aligned);
1800	            if (!SVM_IS_ALIGNED((u64)(uintptr_t)ptr, page_size)) {
1801	                svm_report_addr_not_aligned("halMemMap", "ptr", (u64)(uintptr_t)ptr, page_size);
1802	            } else if (!SVM_IS_ALIGNED(size, page_size)) {
1803	                svm_report_size_not_aligned("halMemMap", "size", size, page_size);
1804	            }
1805	            return DRV_ERROR_PARA_ERROR;
1806	        }
1807	    } else {
1808	        if (aligned < VMM_ALLOC_GRANULARITY_4K) {
1809	            svm_err("Not aligned. (ptr=0x%llx; pg_type=%u; size=%llu; module_id=%u; aligned=%llu)\n",
1810	                    (u64)(uintptr_t)ptr, handle->src_prop.pg_type, (u64)size, handle->src_prop.module_id, aligned);
1811	            if (!SVM_IS_ALIGNED((u64)(uintptr_t)ptr, VMM_ALLOC_GRANULARITY_4K)) {
1812	                svm_report_addr_not_aligned("halMemMap", "ptr", (u64)(uintptr_t)ptr, VMM_ALLOC_GRANULARITY_4K);
1813	            } else if (!SVM_IS_ALIGNED(size, VMM_ALLOC_GRANULARITY_4K)) {
1814	                svm_report_size_not_aligned("halMemMap", "size", size, VMM_ALLOC_GRANULARITY_4K);
1815	            }
1816	            return DRV_ERROR_PARA_ERROR;
1817	        }
1818	    }
1819	    return DRV_ERROR_NONE;
1820	}
1821	
1822	drvError_t halMemMap(void *ptr, size_t size, size_t offset, drv_mem_handle_t *handle, uint64_t flag)
1823	{
1824	    int ret;
1825	
1826	    ret = vmm_mmap_para_check(ptr, size, offset, handle, flag);
1827	    if (ret != 0) {
1828	        return ret;
1829	    }
1830	
1831	    svm_use_pipeline();
1832	    ret = vmm_mmap(ptr, (u64)size, handle, (u64)offset);
1833	    svm_unuse_pipeline();
1834	    if (ret == 0) {
1835	        svm_debug("Vmm Map. (va=0x%llx; size=%llu; handle_va=0x%llx; devid=%u; key=%llu)\n", (u64)(uintptr_t)ptr, size,
1836	                  handle->va, handle->devid, handle->key);
1837	    }
1838	
1839	    return (drvError_t)ret;
1840	}
