1842	drvError_t halMemUnmap(void *ptr)
1843	{
1844	    int ret;
1845	
1846	    if (ptr == NULL) {
1847	        svm_err("Ptr is null.\n");
1848	        return DRV_ERROR_INVALID_VALUE;
1849	    }
1850	
1851	    if (((uintptr_t)ptr % VMM_ALLOC_RECOMMENDED_GRANULARITY) != 0) {
1852	        svm_err("Ptr is invalid. (ptr=%p)\n", ptr);
1853	        svm_report_addr_not_aligned("halMemUnmap", "ptr", (u64)(uintptr_t)ptr, VMM_ALLOC_RECOMMENDED_GRANULARITY);
1854	        return DRV_ERROR_INVALID_VALUE;
1855	    }
1856	    svm_debug("Vmm Unmap. (va=0x%llx)\n", (u64)(uintptr_t)ptr);
1857	
1858	    svm_use_pipeline();
1859	    ret = vmm_munmap(ptr);
1860	    svm_unuse_pipeline();
1861	
1862	    return (drvError_t)ret;
1863	}
