1895	static int vmm_export(drv_mem_handle_t *handle, drv_mem_handle_type handle_type, struct svm_share_handle *share_handle)
1896	{
1897	    struct svm_prop prop;
1898	    struct svm_dst_va dst_va;
1899	    u64 start = handle->va;
1900	    u64 key;
1901	    int ret;
1902	
1903	    ret = svm_get_prop(start, &prop);
1904	    if (ret != 0) {
1905	        svm_err("Get prop failed. (start=%llx)\n", start);
1906	        return ret;
1907	    }
1908	
1909	    if (!svm_flag_cap_is_support_vmm_export(prop.flag)) {
1910	        svm_err("Addr cap is not support vmm export. (start=0x%llx)\n", start);
1911	        return DRV_ERROR_PARA_ERROR;
1912	    }
1913	
1914	    if (prop.devid == svm_get_host_devid()) {
1915	        svm_dst_va_pack(prop.devid, DEVDRV_PROCESS_CPTYPE_MAX, prop.start, prop.aligned_size, &dst_va);
1916	    } else {
1917	        svm_dst_va_pack(prop.devid, DEVDRV_PROCESS_CP1, prop.start, prop.aligned_size, &dst_va);
1918	    }
