1920	    svm_use_pipeline();
1921	    ret = svm_casm_create_key(&dst_va, &key);
1922	    if (ret == 0) {
1923	        handle->type = SVM_VMM_HANDLE_EXPORT_TYPE;
1924	        handle->key = key;
1925	        svm_fill_share_handle(share_handle, handle_type, key, &handle->src_prop);
1926	    }
1927	    svm_unuse_pipeline();
1928	
1929	    return ret;
1930	}
