1932	/* dir: dst device process va -> src device pa */
1933	static int vmm_dir_check(u32 dst_devid, struct svm_global_va *src_va)
1934	{
1935	#define CONNECT_TYPE_NUM (HOST_DEVICE_CONNECT_TYPE_UB + 1)
1936	    u32 host_devid = svm_get_host_devid();
1937	
1938	    if (dst_devid == host_devid) {
1939	        /* not support H2rH, H2rD */
1940	        if ((src_va->server_id != SVM_INVALID_SERVER_ID) && (src_va->server_id != svm_get_cur_server_id())) {
1941	            return DRV_ERROR_NOT_SUPPORT;
1942	        }
1943	
1944	        if (src_va->udevid == host_devid) {
1945	            /* support local H2H */
1946	            return 0;
1947	        } else { /* local H2D */
1948	            /* not support connect with ub, because host mem-decoder not config */
1949	            int h2d_support_flag[CONNECT_TYPE_NUM] = {
1950	                [HOST_DEVICE_CONNECT_TYPE_PCIE] = 1, /* use pcie bar */
1951	                [HOST_DEVICE_CONNECT_TYPE_HCCS] = 1, /* use global pa */
1952	            };
1953	            u32 src_devid, connect_type;
1954	            int ret = drvDeviceGetIndexByPhyId(src_va->udevid, &src_devid);
1955	            if (ret != 0) {
1956	                svm_err("Get src devid failed. (udevid=%u)\n", src_va->udevid);
1957	                return ret;
1958	            }
1959	
1960	            connect_type = svm_get_device_connect_type(src_devid);
1961	            if (connect_type > HOST_DEVICE_CONNECT_TYPE_UB) {
1962	                svm_err("Invalid connect type. (devid=%u; connect_type=%u)\n", dst_devid, connect_type);
1963	                return DRV_ERROR_INVALID_VALUE;
1964	            }
1965	
1966	            return (h2d_support_flag[connect_type] == 1) ? 0 : DRV_ERROR_NOT_SUPPORT;
1967	        }
1968	    } else {
1969	        if (src_va->udevid == host_devid) { /* D2H, D2rH */
1970	            /* D2H is same with D2rH */
1971	            /* not support connect with pcie, because pcie th va is not same */
1972	            int d2h_support_flag[CONNECT_TYPE_NUM] = {
1973	                [HOST_DEVICE_CONNECT_TYPE_HCCS] = 1, /* use global pa */
1974	                [HOST_DEVICE_CONNECT_TYPE_UB] = 1,   /* use memory decoder */
1975	            };
1976	            u32 connect_type = svm_get_device_connect_type(dst_devid);
1977	            if (connect_type > HOST_DEVICE_CONNECT_TYPE_UB) {
1978	                svm_err("Invalid connect type. (devid=%u; connect_type=%u)\n", dst_devid, connect_type);
1979	                return DRV_ERROR_INVALID_VALUE;
1980	            }
1981	
1982	            return (d2h_support_flag[connect_type] == 1) ? 0 : DRV_ERROR_NOT_SUPPORT;
1983	        } else {
1984	            /* support D2D, D2rD */
1985	            return 0;
1986	        }
1987	    }
1988	}
