1990	static int vmm_import(struct svm_share_handle *share_handle, u32 devid, drv_mem_handle_t **handle)
1991	{
1992	    struct drv_mem_prop *src_prop = share_handle->src_prop_valid ? &share_handle->src_prop : NULL;
1993	    struct svm_global_va src_va;
1994	    u64 key = share_handle->key;
1995	    int clr_cs_flag = 0;
1996	    int dir_checked_flag = 0;
1997	    int ret;
1998	
1999	    if ((share_handle->handle_type == MEM_HANDLE_TYPE_FABRIC) && (share_handle->cs_valid != 0)) {
2000	        ret = vmm_dir_check(devid, &share_handle->src_va);
2001	        if (ret != 0) {
2002	            return ret;
2003	        }
2004	        dir_checked_flag = 1;
2005	
2006	        if (share_handle->src_va.server_id != svm_get_cur_server_id()) {
2007	            ret = svm_casm_cs_set_src_info(devid, key, &share_handle->src_va, share_handle->owner_pid);
2008	            if (ret != 0) {
2009	                svm_err("Set cs src failed. (key=0x%llx)\n", key);
2010	                return ret;
2011	            }
2012	            clr_cs_flag = 1;
2013	        }
2014	    }
2015	
2016	    ret = svm_casm_get_src_va(devid, key, &src_va);
2017	    if (ret != 0) {
2018	        if (clr_cs_flag == 1) {
2019	            (void)svm_casm_cs_clr_src_info(devid, key);
2020	        }
2021	        svm_err("Get src va failed. (key=0x%llx)\n", key);
2022	        return ret;
2023	    }
2024	
2025	    if (dir_checked_flag == 0) {
2026	        ret = vmm_dir_check(devid, &src_va);
2027	        if (ret != 0) {
2028	            return ret;
2029	        }
2030	    }
2031	
2032	    *handle = vmm_import_handle_create(devid, key, src_prop, &src_va);
2033	    if (*handle == NULL) {
2034	        if (clr_cs_flag == 1) {
2035	            (void)svm_casm_cs_clr_src_info(devid, key);
2036	        }
2037	        svm_err("Import handle create failed.\n");
2038	        return DRV_ERROR_OUT_OF_MEMORY;
2039	    }
2040	
2041	    (*handle)->clr_cs_flag = share_handle->cs_valid;
2042	
2043	    return 0;
2044	}
