2067	        return DRV_ERROR_INVALID_VALUE;
2068	    }
2069	
2070	    if (handle->type != SVM_VMM_HANDLE_NORMAL_TYPE) {
2071	        /* The log cannot be modified, because in the failure mode library. */
2072	        svm_err("Handle type should be normal type. (type=%u)\n", handle->type);
