2549	static int _vmm_access_node_handle(void *va_handle, u64 va,
2550	                                   int (*func)(struct svm_vmm_access_node *access_node, void *priv), void *priv)
2551	{
2552	    struct svm_vmm_access_node *access_node = NULL;
2553	    void *svmm_inst = NULL;
2554	    void *seg_handle = NULL;
2555	    u32 seg_devid;
2556	    u64 svm_flag, seg_va;
2557	    struct svm_global_va src_info;
2558	    int ret;
2559	
2560	    svmm_inst = vmm_get_svmm(va_handle);
2561	    if (svmm_inst == NULL) {
2562	        svm_err("Vmm alloc not finish. (va=0x%llx)\n", va);
2563	        return DRV_ERROR_PARA_ERROR;
2564	    }
2565	
2566	    seg_handle = svm_svmm_seg_handle_get(svmm_inst, va);
2567	    if (seg_handle == NULL) { /* maybe va has been unmap after get prop or not map */
2568	        svm_err("Get seg handle failed. (va=%llx)\n", va);
2569	        return DRV_ERROR_PARA_ERROR;
2570	    }
2571	
2572	    seg_va = va;
2573	    ret = svm_svmm_get_seg_by_va(svmm_inst, &seg_devid, &seg_va, &svm_flag, &src_info);
2574	    if (ret != 0) {
2575	        svm_svmm_seg_handle_put(seg_handle);
2576	        /* should not in, because we has been get seg handle */
2577	        svm_err("Get seg info failed. (va=%llx)\n", va);
2578	        return ret;
2579	    }
2580	
2581	    access_node = vmm_get_access_node(seg_handle);
2582	    if (access_node == NULL) { /* vmm map addr first set/get access */
2583	        svm_svmm_inst_occupy_pipeline(svmm_inst);
2584	        access_node = vmm_create_access_node(seg_handle, seg_devid, seg_va, src_info.size, &src_info);
2585	        svm_svmm_inst_release_pipeline(svmm_inst);
2586	        if (access_node == NULL) {
2587	            svm_svmm_seg_handle_put(seg_handle);
2588	            return DRV_ERROR_OUT_OF_MEMORY;
2589	        }
2590	    }
2591	
2592	    ret = func(access_node, priv);
2593	    svm_svmm_seg_handle_put(seg_handle);
2594	
2595	    return ret;
2596	}
