134	
135	    ret = mga_inst_init(inst, attr);
136	    if (ret != 0) {
137	        svm_ua_free(inst);
138	        return NULL;
139	    }
140	
141	    return (void *)inst;
142	}
143	
144	static int mga_release_va(u64 start, u64 size, void *priv)
145	{
146	    struct mga_inst *inst = (struct mga_inst *)priv;
147	    int ret = inst->attr.shrink((void *)inst, start, size);
148	    if (ret != 0) {
149	        svm_warn("Free va failed. (ret=%d; start=0x%llx; size=%llu)\n", ret, start, size);
150	    }
151	    /* delete range in destroy ga init, not delete here because: 1. deadlock, 2. range may be not idle */
152	    return 0;
153	}
154	
155	static void mga_release_all_va(struct mga_inst *inst)
156	{
157	    if (inst->ga_inst[inst->base_align_type] != NULL) {
158	        (void)svm_ga_for_each_range(inst->ga_inst[inst->base_align_type], mga_release_va, inst);
159	    }
160	}
161	
162	void mga_inst_destroy(void *mga_inst)
163	{
164	    struct mga_inst *inst = (struct mga_inst *)mga_inst;
165	
166	    mga_release_all_va(inst);
167	
168	    mga_inst_uninit(inst);
169	    svm_ua_free(inst);
170	}
171	
172	static int mga_shrink_sub_ga_once(struct mga_inst *inst, u32 align_type)
173	{
174	    void *base_ga_inst = inst->ga_inst[inst->base_align_type];
175	    void *sub_ga_inst = inst->ga_inst[align_type];
176	    u64 start, size;
177	    int ret;
178	
179	    ret = svm_ga_recycle_one_idle_range(sub_ga_inst, &start, &size);
180	    if (ret == DRV_ERROR_NONE) {
181	        ret = svm_ga_free(base_ga_inst, start, size);
182	        if (ret != DRV_ERROR_NONE) {
183	            svm_err("Unlikely. (start=0x%llx; size=%llu)\n", start, size);
184	            return DRV_ERROR_INNER_ERR;
185	        }
186	    }
187	
188	    return ret;
189	}
190	
191	static int mga_expand_sub_ga_once(struct mga_inst *inst, u32 align_type, u64 size)
192	{
193	    void *base_ga_inst = inst->ga_inst[inst->base_align_type];
194	    void *sub_ga_inst = inst->ga_inst[align_type];
195	    u64 align = mga_align_type_to_size(inst->base_align_type);
196	    u64 expand_size = svm_align_up(size, align);
197	    u64 start;
198	    int ret;
199	
200	    ret = svm_ga_alloc(base_ga_inst, 0, &start, expand_size);
201	    if (ret == DRV_ERROR_NONE) {
202	        ret = svm_ga_add_range(sub_ga_inst, start, expand_size);
203	        if (ret != DRV_ERROR_NONE) {
204	            (void)svm_ga_free(base_ga_inst, start, expand_size);
205	        }
206	    }
207	
208	    return ret;
209	}
210	
211	static void mga_shrink_sub_ga(struct mga_inst *inst, u32 align_type)
212	{
213	    int ret;
214	
215	    do {
216	        ret = mga_shrink_sub_ga_once(inst, align_type);
217	    } while (ret == DRV_ERROR_NONE);
218	}
219	
220	static void mga_shrink_all_sub_ga(struct mga_inst *inst)
221	{
222	    u32 align_type;
223	
224	    for (align_type = MGA_ALIGN_TYPE_4K; align_type < MGA_ALIGN_TYPE_MAX; align_type++) {
225	        if (align_type == inst->base_align_type) {
226	            continue;
227	        }
228	
229	        mga_shrink_sub_ga(inst, align_type);
230	    }
231	}
232	
233	static int mga_expand(struct mga_inst *inst)
234	{
235	    u64 va = 0, size;
236	    int ret;
237	
238	    size = inst->attr.expand_gran;
239	    ret = inst->attr.expand((void *)inst, &size, &va);
240	    if (ret != 0) {
241	        svm_err("Expand va fail. (ret=%d; size=%llu)\n", ret, size);
242	        return ret;
243	    }
244	
245	    ret = svm_ga_add_range(inst->ga_inst[inst->base_align_type], va, size);
246	    if (ret != DRV_ERROR_NONE) {
247	        svm_err("Ga inst add range failed. (ret=%d; start=0x%llx; size=%llu)\n", ret, va, size);
248	        (void)inst->attr.shrink((void *)inst, va, size);
249	        return ret;
250	    }
251	
252	    inst->total_size += size;
253	
254	    return DRV_ERROR_NONE;
255	}
256	
257	static void mga_shrink(struct mga_inst *inst)
258	{
259	    u64 va, size;
260	    int ret;
261	
262	    mga_shrink_all_sub_ga(inst);
263	
264	    ret = svm_ga_recycle_one_idle_range(inst->ga_inst[inst->base_align_type], &va, &size);
265	    if (ret == DRV_ERROR_NONE) {
266	        inst->total_size -= size;
267	        (void)inst->attr.shrink((void *)inst, va, size);
268	    }
269	}
270	
271	static int mga_alloc(struct mga_inst *inst, u32 ga_flag, u32 align_type, u64 size, u64 *va)
272	{
273	    void *ga_inst = inst->ga_inst[align_type];
274	    int ret;
275	
276	    ret = svm_ga_alloc(ga_inst, ga_flag, va, size);
277	    if (ret == DRV_ERROR_NONE) {
278	        return DRV_ERROR_NONE;
279	    }
280	
281	    if (align_type == inst->base_align_type) {
282	        mga_shrink_all_sub_ga(inst);
283	    } else {
284	        ret = mga_expand_sub_ga_once(inst, align_type, size);
285	        if (ret != DRV_ERROR_NONE) {
286	            mga_shrink_all_sub_ga(inst);
287	            ret = mga_expand_sub_ga_once(inst, align_type, size);
288	            if (ret != DRV_ERROR_NONE) {
289	                return DRV_ERROR_OUT_OF_MEMORY;
290	            }
291	        }
292	    }
293	
294	    return svm_ga_alloc(ga_inst, ga_flag, va, size);
295	}
296	
297	static int mga_free(struct mga_inst *inst, u64 va, u64 size, u32 align_type)
298	{
299	    return svm_ga_free(inst->ga_inst[align_type], va, size);
300	}
301	
302	static int _mga_va_alloc(struct mga_inst *inst, u32 align_type, u64 size, u64 *va)
303	{
304	    int ret;
305	
306	    (void)pthread_rwlock_wrlock(&inst->rwlock); /* To ensure the expand is for cur thread */
307	    ret = mga_alloc(inst, 0, align_type, size, va);
308	    if (ret != DRV_ERROR_NONE) {
309	        if (inst->total_size < inst->attr.expand_thres) {
310	            ret = mga_expand(inst);
311	            if (ret == DRV_ERROR_NONE) {
312	                ret = mga_alloc(inst, 0, align_type, size, va);
313	            }
314	        }
315	    }
316	    (void)pthread_rwlock_unlock(&inst->rwlock);
317	
318	    return ret;
319	}
320	
321	static int _mga_va_free(struct mga_inst *inst, u64 va, u64 size, u32 align_type)
322	{
323	    int ret;
324	
325	    (void)pthread_rwlock_wrlock(&inst->rwlock);
326	    ret = mga_free(inst, va, size, align_type);
327	    if (ret == DRV_ERROR_NONE) {
328	        if (inst->total_size > inst->attr.shrink_thres) {
329	            mga_shrink(inst);
330	        }
331	    }
332	    (void)pthread_rwlock_unlock(&inst->rwlock);
333	
334	    return ret;
335	}
336	
337	int mga_va_alloc(void *mga_inst, u64 align, u64 size, u64 *va)
338	{
339	    struct mga_inst *inst = (struct mga_inst *)mga_inst;
340	    u32 align_type = mga_align_size_to_type(align);
341	
342	    if (inst == NULL) {
343	        svm_err("Mga_inst is null.\n");
344	        return DRV_ERROR_INVALID_VALUE;
345	    }
346	
347	    if (align_type >= MGA_ALIGN_TYPE_MAX) {
348	        svm_err("Align size is invalid. (align=%llu)\n", align);
349	        return DRV_ERROR_INVALID_VALUE;
350	    }
351	
352	    return _mga_va_alloc(inst, align_type, size, va);
353	}
354	
355	int mga_va_free(void *mga_inst, u64 va, u64 size, u64 align)
356	{
357	    struct mga_inst *inst = (struct mga_inst *)mga_inst;
358	    u32 align_type = mga_align_size_to_type(align);
359	
360	    if (inst == NULL) {
361	        svm_err("Mga_inst is null.\n");
362	        return DRV_ERROR_INVALID_VALUE;
363	    }
364	
365	    if (align_type >= MGA_ALIGN_TYPE_MAX) {
366	        svm_err("Align size is invalid. (align=%llu)\n", align);
367	        return DRV_ERROR_INVALID_VALUE;
368	    }
369	
370	    return _mga_va_free(inst, va, size, align_type);
371	}
372	
373	u64 mga_get_max_align_size(void *mga_inst)
374	{
375	    struct mga_inst *inst = (struct mga_inst *)mga_inst;
376	    return inst->attr.max_align_size;
377	}
378	
379	u64 mga_get_total_size(void *mga_inst)
380	{
381	    struct mga_inst *inst = (struct mga_inst *)mga_inst;
382	    return inst->total_size;
383	}
